<script setup lang="ts">import { useNotificationStore } from '@/stores/notifications'; const store=useNotificationStore()</script>
<template><div class="page"><header class="page-header"><div><h1>Notifications</h1><p>Updates about tasks, mentions and workspace activity.</p></div><button class="btn" @click="store.markAllRead">Mark all as read</button></header><div class="notification-layout"><aside class="panel notification-filters"><button class="active">All <span>{{store.items.length}}</span></button><button>Unread <span>{{store.unreadCount}}</span></button><button>Mentions</button><button>Assignments</button></aside><section class="panel notification-list"><article v-for="n in store.items" :key="n.id" :class="{unread:!n.isRead}" @click="store.markRead(n.id)"><span class="unread-dot"></span><div><strong>{{n.title}}</strong><p>{{n.message}}</p><small>{{n.createdAt}}</small></div><button class="icon-btn" @click.stop="store.remove(n.id)">×</button></article></section></div></div></template>
